CREATE OR REPLACE FUNCTION public.assess_citizen_tax(_citizen jsonb,_prior jsonb,_day bigint,_rate numeric) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE c jsonb:=_citizen; owner text:=_citizen->'allegiance'->>'userId'; old_owner text:=_prior->'allegiance'->>'userId'; last_day bigint; mood_day bigint; days bigint; cycles bigint; money numeric:=GREATEST(0,COALESCE((_citizen->>'coins')::numeric,0)); mood numeric:=LEAST(100,GREATEST(0,COALESCE((_citizen->>'happiness')::numeric,50))); paid numeric:=0; amount numeric; unhappy bigint; rate numeric:=LEAST(100,GREATEST(0,COALESCE(_rate,0))); BEGIN c:=jsonb_set(c,'{coins}',to_jsonb(money)); IF owner IS NULL OR _rate IS NULL THEN RETURN jsonb_build_object('citizen',c-'taxMoraleCeiling','paid',0); END IF; IF owner IS DISTINCT FROM old_owner OR _prior->>'lastTaxDay' IS NULL THEN last_day:=_day; mood_day:=_day; unhappy:=0; ELSE last_day:=LEAST(_day,(_prior->>'lastTaxDay')::bigint); mood_day:=LEAST(_day,COALESCE((_prior->>'taxMoodDay')::bigint,_day)); unhappy:=COALESCE((_prior->>'taxUnhappyDays')::bigint,0); IF rate>=50 THEN mood:=LEAST(mood,COALESCE((_prior->>'taxMoraleCeiling')::numeric,mood)); END IF; END IF; cycles:=(_day-last_day)/28; WHILE cycles>0 LOOP amount:=floor(money*rate/100); money:=money-amount; paid:=paid+amount; last_day:=last_day+28; cycles:=cycles-1; EXIT WHEN money=0; END LOOP; last_day:=last_day+((_day-last_day)/28)*28; days:=_day-mood_day; mood:=GREATEST(0,mood-days*GREATEST(0,ceil((rate-10)/10))); IF rate>=50 THEN unhappy:=unhappy+days; ELSE unhappy:=0; END IF; c:=(c-'taxMoraleCeiling')||jsonb_build_object('coins',money,'lastTaxDay',last_day,'taxMoodDay',_day,'taxUnhappyDays',unhappy,'happiness',mood,'lastTaxPaid',CASE WHEN paid>0 THEN paid ELSE COALESCE((_prior->>'lastTaxPaid')::numeric,0) END); IF rate>=50 THEN c:=c||jsonb_build_object('taxMoraleCeiling',mood); END IF; IF rate>=50 AND mood<=20 AND unhappy>=7 THEN c:=(c-'allegiance'-'buildingKey'-'partnerId'-'taxMoraleCeiling')||jsonb_build_object('taxExileUntilDay',_day+28,'taxUnhappyDays',0); END IF; RETURN jsonb_build_object('citizen',c,'paid',paid); END $$;
GRANT EXECUTE ON FUNCTION public.assess_citizen_tax(jsonb,jsonb,bigint,numeric) TO authenticated;